CREATE OR REPLACE FUNCTION public.validate_profile_inspector_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if TG_OP = 'UPDATE'
    and old.role = 'inspector'
    and (
      new.role is distinct from old.role
      or new.organization_id is distinct from old.organization_id
      or new.active is distinct from old.active
    )
    and (
      new.role <> 'inspector'
      or new.organization_id is distinct from old.organization_id
      or new.active is false
    )
    and exists (
      select 1
      from public.profiles guard
      where guard.inspector_id = old.id
    )
  then
    raise exception 'Reassign or clear all Guard Inspector assignments before disabling, moving, or changing this Inspector.';
  end if;

  if new.inspector_id is not null then
    if new.role <> 'user' then
      raise exception 'Only Guard accounts can have an assigned Inspector.';
    end if;
    if new.organization_id is null or not exists (
      select 1
      from public.profiles inspector
      where inspector.id = new.inspector_id
        and inspector.organization_id = new.organization_id
        and inspector.role = 'inspector'
        and inspector.active
    ) then
      raise exception 'Assigned Inspector must be active and belong to the same organization.';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_schedule_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles%rowtype;
begin
  if new.approval_status not in ('approved','changed') then return new; end if;
  -- Serialize with category/period edits. Historical completion/cancellation
  -- updates never rewrite the original category or invalidate a time record.
  select * into p from public.profiles where id = new.user_id for share;
  if p.role = 'user' and p.employment_category = 'contract' and (
    p.contract_start_date is null or p.contract_end_date is null or
    new.start_at < (p.contract_start_date::timestamp at time zone 'Asia/Manila') or
    new.end_at > ((p.contract_end_date + 1)::timestamp at time zone 'Asia/Manila')) then
    raise exception 'Duty must start and finish within the Guard contract dates. Set or renew the contract in Personnel.';
  end if;
  new.duty_category := case when p.role = 'user' then p.employment_category else null end;
  return new;
end;
$function$

