CREATE OR REPLACE FUNCTION public.notify_schedule_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_message text;
  v_dedupe text;
begin
  if tg_op = 'UPDATE' and new.user_id is distinct from old.user_id then
    perform public.insert_user_notification(
      old.user_id, old.organization_id, 'schedule', 'high',
      'Duty schedule reassigned',
      'A duty previously assigned to you was reassigned. Review your current schedule.',
      'schedule', 'schedule', old.id, '{}'::jsonb, false, auth.uid(),
      'schedule:' || old.id::text || ':removed:' || old.user_id::text,
      now() + interval '90 days'
    );
  end if;

  if new.approval_status not in ('approved', 'changed', 'cancelled') then
    return new;
  end if;
  if tg_op = 'UPDATE' and not (
    new.user_id is distinct from old.user_id
    or new.location_id is distinct from old.location_id
    or new.location_label is distinct from old.location_label
    or new.start_at is distinct from old.start_at
    or new.end_at is distinct from old.end_at
    or new.approval_status is distinct from old.approval_status
  ) then
    return new;
  end if;

  v_message := case when new.approval_status = 'cancelled'
    then 'Your duty at ' || coalesce(nullif(new.location_label, ''), 'the assigned post') || ' was cancelled.'
    else 'Duty at ' || coalesce(nullif(new.location_label, ''), 'your assigned post') ||
      ' starts ' || to_char(new.start_at at time zone 'Asia/Manila', 'Mon DD, YYYY at HH12:MI AM') ||
      ' and ends ' || to_char(new.end_at at time zone 'Asia/Manila', 'Mon DD, YYYY at HH12:MI AM') || '.'
  end;
  v_dedupe := 'schedule:' || new.id::text || ':' || md5(concat_ws('|',
    new.user_id::text, coalesce(new.location_id::text, ''), coalesce(new.location_label, ''),
    new.start_at::text, new.end_at::text, new.approval_status
  ));

  perform public.insert_user_notification(
    new.user_id, new.organization_id, 'schedule',
    case when new.approval_status = 'cancelled' then 'high' else 'normal' end,
    case
      when new.approval_status = 'cancelled' then 'Duty schedule cancelled'
      when tg_op = 'INSERT' then 'New duty schedule'
      else 'Duty schedule updated'
    end,
    v_message,
    'schedule', 'schedule', new.id,
    jsonb_build_object('start_at', new.start_at, 'end_at', new.end_at, 'status', new.approval_status),
    false, auth.uid(), v_dedupe, new.end_at + interval '30 days'
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_overlapping_active_schedules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      new.organization_id::text || ':' || new.user_id::text,
      0
    )
  );

  if new.approval_status in ('approved', 'changed') and exists (
    select 1
    from public.schedules existing
    where existing.user_id = new.user_id
      and existing.organization_id = new.organization_id
      and existing.id <> coalesce(new.id, gen_random_uuid())
      and existing.approval_status in ('approved', 'changed')
      and existing.start_at < new.end_at
      and existing.end_at > new.start_at
  ) then
    raise exception 'This personnel member already has an overlapping active schedule.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_schedule_history_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.attendance_sessions where schedule_id = old.id) then
    raise exception 'This schedule has recorded attendance and must be kept for the guard''s DTR.'
      using detail = 'SCHEDULE_ATTENDANCE_HISTORY';
  end if;
  if old.marked_done or old.completed_at is not null then
    raise exception 'Completed duty schedules must be kept for historical records.'
      using detail = 'SCHEDULE_COMPLETED_HISTORY';
  end if;
  if exists (select 1 from public.accomplishment_reports where schedule_id = old.id) then
    raise exception 'This schedule has an accomplishment report and must be kept for historical records.'
      using detail = 'SCHEDULE_REPORT_HISTORY';
  end if;
  if exists (select 1 from public.shift_swap_requests where requested_schedule_id = old.id) then
    raise exception 'This schedule has a shift-change request and must be kept for approval history.'
      using detail = 'SCHEDULE_CHANGE_HISTORY';
  end if;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_started_schedule_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (
    new.user_id is distinct from old.user_id
    or new.location_id is distinct from old.location_id
    or new.start_at is distinct from old.start_at
    or new.end_at is distinct from old.end_at
    or new.dtr_period is distinct from old.dtr_period
    or new.duty_date is distinct from old.duty_date
  ) and exists (
    select 1 from public.attendance_sessions session
    where session.schedule_id = old.id and session.clock_in_at is not null
  ) then
    raise exception 'A started duty cannot be changed. Create a corrected replacement schedule instead.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_clock_in_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles%rowtype; s public.schedules%rowtype;
begin
  select * into p from public.profiles where id = new.user_id for share;
  if p.role = 'user' and p.employment_category = 'contract' then
    select * into s from public.schedules where id = new.schedule_id;
    if p.contract_start_date is null or p.contract_end_date is null or
      s.start_at < (p.contract_start_date::timestamp at time zone 'Asia/Manila') or
      s.end_at > ((p.contract_end_date + 1)::timestamp at time zone 'Asia/Manila') or
      (now() at time zone 'Asia/Manila')::date not between p.contract_start_date and p.contract_end_date then
      raise exception 'Time In is unavailable outside your contract period. Ask Admin to set or renew your contract dates.';
    end if;
  end if;
  return new;
end;
$function$
